package com.fooddelivery.security;
import com.fooddelivery.repository.UserRepository; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.*; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import org.springframework.web.cors.*; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
@Configuration public class SecurityConfig { @Bean CorsConfigurationSource corsConfigurationSource(){var c=new CorsConfiguration();c.setAllowedOrigins(java.util.List.of("http://localhost:5173"));c.setAllowedMethods(java.util.List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(java.util.List.of("*"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s;} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService userDetailsService(UserRepository r){return email->r.findByEmail(email).map(u->User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).build()).orElseThrow(()->new UsernameNotFoundException("User not found"));} @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();} @Bean SecurityFilterChain chain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/restaurants/**","/api/menu/**","/api/health").permitAll().requestMatchers("/api/orders/**").hasAnyRole("CUSTOMER","ADMIN").anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} }
@Component class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserDetailsService uds; JwtFilter(JwtService jwt,UserDetailsService uds){this.jwt=jwt;this.uds=uds;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String token=h.substring(7),u=jwt.username(token);UserDetails d=uds.loadUserByUsername(u);if(jwt.valid(token,d)) SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}}chain.doFilter(req,res);} }